window.RXC.push(
{n:'Hipertireoidismo (Graves / nódulo tóxico) — ambulatório',cid:'E05.0 / E05.9',sp:'Endocrinologia',ps:[{v:'CONDUTA NO CONSULTÓRIO',i:['Confirmar: TSH suprimido (< 0,1) + T4 livre ↑ (± T3 ↑ — T3-toxicose); subclínico = TSH baixo com T4L/T3 normais (tratar se TSH < 0,1 persistente em > 65 a, cardiopata, osteoporose, sintomas); ETIOLOGIA: TRAb (positivo = Graves — bócio difuso, oftalmopatia, mixedema pré-tibial), USG com Doppler (vascularização ↑ Graves; nódulo — bócio multinodular/adenoma tóxico), cintilografia com captação (↑ difusa Graves; focal nódulo; ↓ tireoidite/factícia/iodo); excluir tireoidite (subaguda — dor cervical + VHS ↑ + captação baixa; pós-parto; indolor) — autolimitada, só betabloqueador; medicamentos (amiodarona, iodo, lítio, imunoterapia, biotina — interfere no ensaio); gestação (hCG); hemograma, TGO/TGP (basal antes de tionamida), glicemia, lipídios, Ca, ECG (FA em 10–20%)','SINTOMÁTICO IMEDIATO: PROPRANOLOL 20–40 mg 8/8–6/6 h (ou atenolol 25–100 mg/dia) para palpitação/tremor/ansiedade até eutireoidismo (asma: diltiazem/verapamil); FA: anticoagular conforme CHA₂DS₂-VASc e controlar FC; TEMPESTADE TIREOIDIANA (febre, taquicardia > 140, agitação/delirium, ICC, icterícia — Burch-Wartofsky ≥ 45) → UTI: propiltiouracil/metimazol dose alta + iodo (1 h após) + propranolol + hidrocortisona','GRAVES — 3 opções (decisão compartilhada): 1) ANTITIREOIDIANO (1ª linha no Brasil/Europa, especialmente jovem, leve-moderado, bócio pequeno, oftalmopatia ativa, gestante, criança): METIMAZOL 10–30 mg/dia 1×/dia (dose conforme T4L: leve 10–15; moderado 20; grave 30–40), reduzir a cada 4–6 semanas conforme T4L (não pelo TSH, que fica suprimido por meses) até manutenção 5–10 mg por 12–18 meses, então tentar suspender (remissão 40–50%; TRAb negativo ao fim prediz remissão); PROPILTIOURACIL 100 mg 8/8 h só no 1º trimestre da gestação e na tempestade (hepatotoxicidade); efeitos: rash/prurido (anti-H1 ou trocar), artralgia, AGRANULOCITOSE (0,3% — febre/odinofagia → suspender e hemograma URGENTE; orientar por escrito), hepatite colestática, vasculite ANCA; hemograma e TGO/TGP basais; 2) IODO RADIOATIVO (I-131 — definitivo; preferido nos EUA, em recidiva, bócio nodular tóxico, > 40–50 a, cardiopata): contraindicado em gestação/lactação (β-hCG antes; contracepção 6 meses), oftalmopatia moderada-grave ativa (piora — prednisona profilática se leve/tabagista); resulta em hipotireoidismo (levotiroxina depois); 3) TIREOIDECTOMIA total (bócio volumoso/compressivo, nódulo suspeito, oftalmopatia grave, desejo de gestar logo, falha/intolerância): preparar com metimazol + iodeto (Lugol) 10 dias antes; cirurgião experiente (hipoparatireoidismo/lesão recorrencial)','NÓDULO TÓXICO/BÓCIO MULTINODULAR: não remite — tratamento definitivo (I-131 ou cirurgia); metimazol como ponte/idoso frágil; TIREOIDITE SUBAGUDA: AINE/prednisona 20–40 mg (dor), betabloqueador; fase de hipotireoidismo transitório — não tratar com tionamida; OFTALMOPATIA: cessar tabagismo (principal), selênio 100 mcg 12/12 h por 6 meses (leve), lubrificantes, controle rigoroso do eutireoidismo; moderada-grave ativa → corticoide EV em pulsos/teprotumumabe (oftalmo/endocrino)','SEGUIMENTO: T4L (e T3) a cada 4–6 semanas até normalizar, depois TSH/T4L a cada 2–3 meses durante o tratamento; TRAb aos 12–18 meses antes de suspender; após remissão: TSH a cada 3–6 meses no 1º ano e depois anual (recidiva ~50%); após I-131: TSH/T4L a cada 4–6 semanas por 6 meses (hipotireoidismo em 80% em 1 ano → levotiroxina); gestante: PTU no 1º tri → metimazol após; menor dose que mantenha T4L no limite superior; TRAb no 3º tri (risco fetal); ENCAMINHAR à endocrinologia: Graves (idealmente todos para decidir definitivo), oftalmopatia, nódulo, gestante, criança, recidiva, intolerância, cardiopatia/FA, tempestade']}],casa:[{v:'USO ORAL',i:[['Metimazol 5 mg e 10 mg (Tapazol®)','30–90 comprimidos','Tomar ___ mg (ex.: 20 mg = 2 cp de 10 mg) 1×/dia pela manhã, todos os dias; a dose será reduzida a cada 4–6 semanas conforme o T4 livre; tratamento por 12–18 meses; se FEBRE ou DOR DE GARGANTA/ferida na boca: PARAR e fazer hemograma no mesmo dia'],['Propranolol 40 mg (ou atenolol 25–50 mg 1×/dia)','60–90 comprimidos','Tomar ½–1 comprimido de 8/8 h (ou 6/6 h se taquicardia intensa) enquanto houver palpitação/tremor; reduzir e suspender quando os hormônios normalizarem (não parar bruscamente); não usar se asma'],['Propiltiouracil 100 mg — APENAS 1º trimestre da gestação (depois trocar por metimazol) ou intolerância ao metimazol','90 comprimidos','Tomar 1 comprimido de 8/8 h (100–300 mg/dia conforme gravidade); TGO/TGP se náuseas/icterícia/urina escura'],['Selênio 100 mcg (selenometionina) — oftalmopatia leve (6 meses)','60 comprimidos','Tomar 1 comprimido de 12/12 h por 6 meses'],['Lágrima artificial / gel lubrificante ocular (oftalmopatia — olho seco, exposição)','1 frasco','1–2 gotas de 4/4 h; gel à noite; óculos escuros; elevar a cabeceira'],['Anticoncepção eficaz durante o tratamento (metimazol: evitar gestar nos primeiros 3 meses/dose alta; I-131: 6 meses)','—','Planejar gestação com a endocrinologia (eutireoidismo estável)'],['Exames: T4 livre (+ T3) a cada 4–6 semanas até normalizar; TSH/T4L a cada 2–3 meses; TRAb (diagnóstico e antes de suspender); hemograma + TGO/TGP basais (e imediatamente se febre/dor de garganta/icterícia); USG de tireoide; cintilografia/captação se dúvida; ECG; Ca, glicemia, lipídios; β-hCG antes de I-131','—','Levar ao retorno em 4–6 semanas']]}],ori:['O hipertireoidismo (tireoide "acelerada") tem tratamento eficaz; o metimazol começa a agir em 2–4 semanas e os sintomas (palpitação, tremor, calor, perda de peso, ansiedade, insônia) melhoram em 4–8 semanas; o propranolol alivia enquanto isso; o tratamento com comprimidos dura 12–18 meses e depois tentamos suspender (metade fica curada; a outra metade pode precisar de iodo radioativo ou cirurgia — vamos decidir juntos)','ALERTA DO METIMAZOL/PROPILTIOURACIL: se tiver FEBRE, DOR DE GARGANTA, feridas na boca ou infecção → PARAR o remédio e fazer HEMOGRAMA NO MESMO DIA (raro, mas pode baixar as defesas — agranulocitose); icterícia (olhos amarelos), urina escura, dor abdominal → parar e procurar atendimento (fígado); coceira/manchas leves: avisar (antialérgico/troca); não engravidar sem planejar (o remédio e a dose precisam ser ajustados — avisar imediatamente se engravidar; amamentar é permitido com metimazol ≤ 20 mg)','Hábitos: PARAR DE FUMAR (piora muito a doença dos olhos e reduz a chance de cura), evitar excesso de iodo (algas/kelp, suplementos, contraste iodado sem avisar), reduzir cafeína/energéticos/álcool enquanto acelerado, repouso relativo e sono; alimentação adequada (perde-se massa muscular — proteína); atividade física leve até normalizar (evitar esforço intenso com FC alta); olhos: lubrificante, óculos escuros, cabeceira elevada, não coçar','NÃO parar o metimazol por conta própria quando melhorar (a doença volta); tomar todos os dias no mesmo horário; o propranolol vai sendo retirado aos poucos; se for fazer iodo radioativo: contracepção por 6 meses, afastamento de crianças/gestantes por alguns dias (orientação do serviço), depois provavelmente levotiroxina para a vida toda (simples e segura)','Retornos a cada 4–6 semanas no início (exames de T4 livre antes), depois a cada 2–3 meses; após terminar, exames a cada 3–6 meses no 1º ano (pode voltar); mulheres: avisar se planeja engravidar (ideal: ≥ 6 meses estável)'],al:['FEBRE, dor de garganta, aftas/feridas na boca, infecção (agranulocitose — parar o remédio e hemograma urgente/PS)','Olhos/pele amarelos, urina escura, náuseas/dor abdominal intensa (hepatite medicamentosa)','Palpitações muito fortes/irregulares, dor no peito, falta de ar, inchaço de pernas, desmaio (fibrilação atrial/insuficiência cardíaca) → PS','Febre alta + agitação/confusão + coração muito acelerado + vômitos/diarreia (crise/tempestade tireoidiana — emergência, sobretudo após infecção/cirurgia/parar o remédio) → SAMU 192','Olho vermelho/dor/visão dupla ou embaçada, olho que não fecha (oftalmopatia — oftalmologista urgente); fraqueza súbita das pernas (paralisia periódica hipocalêmica — PS)'],ref:'ATA Guidelines for Diagnosis and Management of Hyperthyroidism 2016 (Ross); ETA Guideline Graves\' Hyperthyroidism 2018 (Kahaly); EUGOGO 2021 (oftalmopatia — Bartalena); SBEM — Consenso Brasileiro de Hipertireoidismo 2013 e Atualização 2020; ATA Thyroid and Pregnancy 2017; Burch & Wartofsky 1993 (tempestade); Cochrane 2010 (tionamidas — duração 12–18 m); Marcocci NEJM 2011 (selênio); Smith & Hegedüs NEJM 2016 (Graves — revisão); Kahaly Lancet 2020.'},
{n:'Insônia crônica (ambulatório)',cid:'G47.0 / F51.0',sp:'Saúde mental',ps:[{v:'CONDUTA NO CONSULTÓRIO',i:['Definir: dificuldade de iniciar/manter o sono ou despertar precoce ≥ 3 noites/semana por ≥ 3 meses, com prejuízo diurno, apesar de oportunidade adequada (ICSD-3); diário de sono por 2 semanas (hora de deitar/levantar, latência, despertares, cochilos, cafeína/álcool, remédios) e Índice de Gravidade de Insônia (ISI); investigar/tratar COMORBIDADES (insônia raramente é "primária"): APNEIA DO SONO (ronco, pausas, sonolência diurna, obesidade, HAS resistente — STOP-BANG → polissonografia; não sedar!), síndrome das pernas inquietas (ferritina < 50–75 → ferro), depressão/ansiedade/TEPT/bipolar (PHQ-9/GAD-7), dor crônica, noctúria/HPB, DRGE, hipertireoidismo (TSH), menopausa (fogachos), asma/DPOC noturnos, IC, demência, medicamentos (corticoide, betabloqueador, ISRS ativadores, bupropiona, estimulantes/metilfenidato, descongestionantes, diuréticos à noite, teofilina, cafeína/nicotina/álcool — álcool fragmenta o sono), turnos/jet lag, distúrbio de fase (adolescente — atraso; idoso — avanço)','1ª LINHA = TERAPIA COGNITIVO-COMPORTAMENTAL PARA INSÔNIA (TCC-I) — superior e mais durável que medicação (AASM 2021/ACP 2016; efeito mantido após parar): CONTROLE DE ESTÍMULOS (cama só para dormir/sexo; deitar só com sono; se não dormir em ~20 min, levantar e voltar quando sonolento; acordar sempre no MESMO horário; sem cochilos > 20 min antes das 15 h), RESTRIÇÃO DE SONO (limitar o tempo na cama ao tempo real dormido — mín. 5–5,5 h — e ampliar 15 min/semana quando eficiência > 85–90%), reestruturação cognitiva (preocupação com o sono/catastrofização), relaxamento/respiração/mindfulness, higiene do sono (coadjuvante — insuficiente sozinha); 4–8 sessões presenciais (psicologia), em grupo, ou DIGITAL (apps/livros — eficaz; ex.: Sleepio, CBT-i Coach, "Durma bem" — Cochrane 2023)','FARMACOTERAPIA — adjuvante, menor dose, curto prazo (≤ 4 semanas ou intermitente 2–3×/semana), com plano de retirada: HIPNÓTICOS Z (zolpidem 5 mg mulher/idoso – 10 mg; eszopiclona 1–3 mg; zopiclona 3,75–7,5 mg) para insônia inicial — sonambulismo/amnésia/quedas; evitar em idoso/apneia; DOXEPINA 3–6 mg (manutenção, idoso — não sedativo anticolinérgico nessa dose); TRAZODONA 25–100 mg (comorbidade depressiva/ansiedade; evidência limitada para insônia isolada; hipotensão/priapismo); MIRTAZAPINA 7,5–15 mg (depressão + insônia + baixo apetite; ganho de peso); MELATONINA 2–5 mg 1–3 h antes de deitar (distúrbio de fase, idoso, jet lag — efeito pequeno; liberação prolongada 2 mg ≥ 55 a); agonistas de orexina (daridorexant 25–50 mg; lemborexant — aprovados 2023–24; seguros em idosos/apneia leve; custo); AMITRIPTILINA 10–25 mg (dor crônica associada — anticolinérgica), QUETIAPINA 25–50 mg: NÃO para insônia isolada (metabólico/QT — só se psiquiátrica); BENZODIAZEPÍNICOS (clonazepam, diazepam, lorazepam, midazolam): EVITAR — tolerância em semanas, dependência, quedas/fraturas, cognição/demência?, acidentes, depressão respiratória com álcool/opioides/apneia; se já em uso crônico: DESMAME lento (↓ 10–25% a cada 2–4 semanas, converter para diazepam se necessário) com TCC-I; anti-histamínicos (prometazina/difenidramina/doxilamina): não recomendados; fitoterápicos (valeriana, passiflora): evidência fraca, baixo risco','IDOSO: priorizar TCC-I/higiene/luz matinal/atividade; evitar Z, BZD, anti-H1, antipsicóticos (Beers); doxepina 3 mg/melatonina/trazodona baixa dose se necessário; avaliar demência/depressão/dor/noctúria; GESTANTE: TCC-I; doxilamina 25 mg (+ B6) é opção; evitar BZD/Z; CRIANÇA/ADOLESCENTE: higiene/rotina/telas/melatonina 1–3 mg em TEA/TDAH sob orientação','SEGUIMENTO em 2–4 semanas com diário/ISI; reavaliar medicação a cada consulta (meta: retirar); encaminhar: suspeita de apneia (polissonografia/medicina do sono), pernas inquietas refratária, parassonias, narcolepsia, insônia refratária à TCC-I + 2 fármacos, psiquiatria se comorbidade grave/dependência de BZD; atestado não é indicado de rotina; dirigir: não após hipnótico/sedativo'],}],casa:[{v:'USO ORAL (adjuvante à TCC-I; menor dose, tempo limitado, plano de retirada)',i:[['Zolpidem 5 mg (mulheres/idosos/hepatopatas) ou 10 mg — insônia INICIAL (receita B1 — azul)','10–14 comprimidos','Tomar 1 comprimido imediatamente antes de deitar (já na cama, com ≥ 7 h disponíveis para dormir), NO MÁXIMO 2–3 noites por semana ou por até 2–4 semanas; não repetir a dose à noite; não dirigir/operar máquinas após; nunca com álcool; comportamentos durante o sono (comer, andar, dirigir) sem lembrar → suspender'],['OU Trazodona 50 mg (25–100 mg) — se ansiedade/depressão associada ou para substituir benzodiazepínico (receita C1)','30 comprimidos','Tomar ½–1 comprimido 30–60 min antes de dormir; levantar devagar (tontura); ereção prolongada → PS'],['OU Doxepina 3–6 mg (manipulada) — insônia de MANUTENÇÃO/despertares, idosos','30 cápsulas','Tomar 1 cápsula 30 min antes de deitar (não com refeição pesada); não com IMAO/glaucoma de ângulo fechado'],['OU Melatonina 2–5 mg (3 mg; liberação prolongada 2 mg se ≥ 55 a) — dificuldade de iniciar/fase atrasada/idoso/jet lag','30 comprimidos','Tomar 1 comprimido 1–3 h ANTES do horário desejado de dormir, todos os dias no mesmo horário, por 4–8 semanas (luz baixa após tomar)'],['OU Mirtazapina 15 mg — insônia + depressão + perda de apetite/peso','30 comprimidos','Tomar ½–1 comprimido ao deitar'],['OU Daridorexant 25–50 mg (Quviviq®) — insônia crônica sem resposta/contraindicação aos demais (sem dependência; idosos/apneia leve)','30 comprimidos','Tomar 1 comprimido 30 min antes de deitar (≥ 7 h de sono), com ou sem alimento (não com refeição pesada)'],['DESMAME de benzodiazepínico em uso crônico (ex.: clonazepam 2 mg): reduzir 0,25–0,5 mg a cada 2–4 semanas (10–25%), últimas etapas mais lentas; associar TCC-I; opcional converter para diazepam equivalente','conforme dose','Não parar bruscamente (abstinência/convulsão); retorno a cada 2–4 semanas durante a retirada'],['Sulfato ferroso 40–60 mg Fe/dia (dias alternados) — se pernas inquietas com ferritina < 75 ng/mL','60 comprimidos','Em jejum com vitamina C, por 3–6 meses; ferritina em 3 meses'],['Exames conforme suspeita: TSH, hemograma + ferritina (pernas inquietas), glicemia, creatinina, vitamina D/B12; polissonografia (ronco/pausas/sonolência diurna, IMC ↑, HAS resistente — STOP-BANG ≥ 3); PHQ-9/GAD-7; diário de sono 2 semanas + ISI','—','Trazer o diário ao retorno em 2–4 semanas'],['Encaminhamentos: psicologia — TCC para insônia (TCC-I; 4–8 sessões; grupo ou online/app), medicina do sono se apneia/parassonia/refratária, psiquiatria se depressão/ansiedade grave ou dependência de calmantes','—','—']]}],ori:['O tratamento mais eficaz e duradouro para insônia crônica NÃO é remédio: é mudar a relação com a cama e o horário (TCC-I) — remédio para dormir é só uma ajuda temporária e perde o efeito/vicia com o tempo','CONTROLE DE ESTÍMULOS: (1) ir para a cama SÓ quando estiver com sono; (2) cama é só para dormir (e sexo) — nada de TV, celular, trabalho, comer, "descansar"; (3) se não dormir em ~20 minutos (ou acordar e não voltar a dormir), LEVANTAR, ir para outro cômodo com luz baixa, fazer algo calmo e chato (ler papel, ouvir música), e só voltar quando sentir sono — repetir quantas vezes precisar; (4) ACORDAR TODOS OS DIAS NO MESMO HORÁRIO (despertador), inclusive fins de semana e mesmo que tenha dormido mal; (5) nada de cochilos (ou no máximo 20 min antes das 15 h)','RESTRIÇÃO DE SONO (parece contraditório, mas é o que mais funciona): calcule quanto realmente dorme por noite (diário) e fique na cama só esse tempo (mínimo 5–5,5 h) — ex.: dorme 5,5 h → deitar à 0h30 e levantar às 6h; quando estiver dormindo bem (> 85–90% do tempo na cama) por 1 semana, antecipar o horário de deitar em 15 min; a sonolência nas primeiras semanas é esperada e é o que "conserta" o sono (não dirigir sonolento)','HIGIENE DO SONO (ajuda, mas sozinha não resolve): sem cafeína após 14 h (café, chá preto/mate/verde, refrigerante de cola, energético, chocolate em excesso), sem álcool como "indutor" (dá sono mas fragmenta e piora o ronco), sem nicotina à noite, jantar leve 2–3 h antes, exercício regular (mas não nas 3 h antes de deitar), LUZ DO SOL pela manhã (15–30 min — regula o relógio) e luz baixa à noite, telas desligadas 1 h antes (ou filtro/brilho mínimo — e NUNCA na cama), quarto escuro/silencioso/fresco (18–22 °C), rotina de desaceleração (banho morno, alongamento, respiração 4-7-8, leitura), não olhar o relógio durante a noite (virar o despertador), "hora da preocupação" no fim da tarde (anotar pendências/soluções em papel), não tentar "forçar" o sono','Se usar remédio: só nas noites/período combinado, menor dose, nunca aumentar sozinho nem misturar com álcool/outros calmantes/opioides; não dirigir após; calmantes (clonazepam, diazepam, alprazolam) viciam e aumentam quedas/perda de memória — se já usa, a retirada será lenta e acompanhada; retorno em 2–4 semanas com o DIÁRIO DE SONO (hora que deitou, demorou para dormir, despertares, hora que levantou, cochilos, cafeína/álcool)'],al:['Ronco alto com pausas na respiração, engasgos à noite, sono não reparador e MUITA sonolência de dia (cochila dirigindo/trabalhando), dor de cabeça matinal, pressão alta difícil → apneia do sono (avaliar — não usar calmantes)','Noites inteiras sem sono acompanhadas de energia aumentada, falar muito, ideias aceleradas, gastos/impulsividade (mania → psiquiatria urgente); pensamentos de morte/desesperança (depressão — procurar ajuda/CVV 188)','Comportamentos durante o sono sem memória (andar, comer, dirigir) com zolpidem — suspender e avisar; confusão, quedas, perda de memória com sedativos (sobretudo idosos); sonolência excessiva ao dirigir','Formigamento/inquietação nas pernas à noite que melhora ao mexer (pernas inquietas — dosar ferritina), cãibras, dor ou falta de ar noturna, necessidade de urinar várias vezes (investigar causa)'],ref:'AASM Clinical Practice Guideline — Behavioral and Psychological Treatments for Chronic Insomnia 2021 (Edinger) e Pharmacologic Treatment 2017 (Sateia); ACP 2016 (Qaseem — TCC-I 1ª linha); European Insomnia Guideline 2023 (Riemann); Associação Brasileira do Sono — Consenso Brasileiro de Insônia 2023 (Bacelar/Pinto Jr.); ICSD-3 (2014/2023); Cochrane 2023 (TCC-I digital — Hasan/Soh), 2018 (BZD/Z em idosos), 2024 (orexinas); AGS Beers Criteria 2023; Trauer Ann Intern Med 2015 (TCC-I meta-análise); Mignot Lancet Neurol 2022 (daridorexant); Krystal Sleep 2010 (doxepina baixa dose); Bastien 2001 (ISI); Chung 2008 (STOP-BANG).'},
{n:'Lombalgia crônica (> 12 semanas) — ambulatório',cid:'M54.5 / M51.1',sp:'Reumatologia',ps:[{v:'CONDUTA NO CONSULTÓRIO',i:['Reavaliar RED FLAGS a cada consulta (câncer/perda de peso/dor noturna, febre/infecção/uso de drogas EV/imunossupressão, trauma/osteoporose/corticoide — fratura, déficit neurológico progressivo, síndrome da cauda equina — retenção/incontinência/anestesia em sela → urgência, aneurisma de aorta em > 60 a, rigidez matinal > 30 min + melhora com exercício + < 45 a + despertar na 2ª metade da noite → ESPONDILOARTRITE AXIAL: HLA-B27/PCR/RM de sacroilíacas → reumatologia); classificar: inespecífica (85–90%), radicular (ciática — dor irradiada abaixo do joelho, Lasègue, déficit em dermátomo; hérnia discal), estenose de canal (claudicação neurogênica — idoso, melhora ao sentar/fletir), síndrome facetária/sacroilíaca, dor com sensibilização central/fibromialgia (dor difusa, sono, fadiga — FIQ); avaliar FATORES PSICOSSOCIAIS ("yellow flags": catastrofização, medo-evitação, depressão/ansiedade, insatisfação no trabalho, litígio/benefício, expectativas) — STarT Back (estratificação de risco) ou Örebro — são os maiores preditores de cronificação','IMAGEM: NÃO repetir/solicitar RX/RM sem red flags ou déficit neurológico progressivo/candidato a intervenção (achados degenerativos são universais e não correlacionam com dor — "disco desidratado/protrusão" em 30–50% de assintomáticos; imagem desnecessária ↑ cirurgia e cronificação); RM se radiculopatia > 6–12 semanas sem melhora e considerando infiltração/cirurgia, estenose sintomática, suspeita de espondiloartrite/infecção/tumor/fratura; eletroneuromiografia se dúvida de radiculopatia × neuropatia','TRATAMENTO — NÃO FARMACOLÓGICO É O CENTRO (NICE/ACP/Lancet): EXERCÍCIO (qualquer modalidade que o paciente mantenha — fortalecimento de core, pilates, yoga, caminhada, natação, tai chi, musculação; supervisionado por fisioterapeuta no início, 2–3×/sem, progressivo; "a coluna é forte e feita para se mover"), EDUCAÇÃO EM DOR (neurociência: dor ≠ dano; evitar repouso/colete/"cuidado excessivo"; retomar atividades/trabalho gradualmente — pacing), TERAPIA COGNITIVO-COMPORTAMENTAL/aceitação (ACT) e mindfulness (MBSR — tão eficazes quanto TCC), programa multidisciplinar (biopsicossocial) se alto risco/incapacidade, terapia manual (manipulação/mobilização) e acupuntura como ADJUVANTES ao exercício (efeito pequeno/curto), calor local; sono, peso, tabagismo (↑ dor crônica), atividade laboral (adaptações; evitar afastamento prolongado — > 6 meses afastado = 50% não retornam); NÃO recomendados: repouso no leito, colete/cinta, tração, TENS/ultrassom/laser/ondas curtas isolados, palmilhas, "desbloqueio" repetido, injeções de pontos-gatilho de rotina','FARMACOLÓGICO (adjuvante, intermitente, menor dose — nenhum altera o curso): AINE (naproxeno 250–500 mg 12/12 h; ibuprofeno 400–600 mg 8/8 h; celecoxibe 200 mg) em CURSOS curtos (≤ 2–4 sem) nas exacerbações, com IBP se risco — efeito pequeno; DULOXETINA 30 → 60 mg (1ª escolha farmacológica para dor crônica — ↓ dor/incapacidade; também depressão/ansiedade); AMITRIPTILINA 10–25 mg à noite (sono/dor neuropática — evidência fraca; não em idoso/cardiopata) ou nortriptilina; GABAPENTINA/PREGABALINA: NÃO em lombalgia/ciática inespecífica (sem benefício — PRECISE; só dor neuropática definida/estenose com parestesia — benefício duvidoso); RELAXANTES (ciclobenzaprina 5–10 mg à noite): só em exacerbação aguda ≤ 7 dias (sedação); PARACETAMOL: sem eficácia (PACE — ACP contra); DIPIRONA 500 mg–1 g como resgate; OPIOIDES: EVITAR (tramadol/codeína: ↓ dor mínima, dependência, ↑ incapacidade a longo prazo — SPACE: não superior a não opioides; só exceção muito selecionada, curta, com contrato); CORTICOIDE sistêmico: sem benefício; canabinoides: não; vitamina D só se deficiente; INTERVENÇÕES: infiltração epidural de corticoide para radiculopatia refratária > 6 semanas (alívio curto, ↓ cirurgia?); bloqueio/radiofrequência facetária em dor facetária confirmada por bloqueio-teste (benefício modesto — MINT negativo); cirurgia (microdiscectomia): ciática com déficit progressivo/cauda equina ou dor radicular incapacitante > 6–12 sem concordante com RM (resultado igual ao conservador em 1–2 anos; alivia mais rápido); artrodese para lombalgia inespecífica/degenerativa: NÃO (igual à reabilitação intensiva); estenose com claudicação incapacitante refratária → descompressão','SEGUIMENTO: reavaliar em 4–6 semanas (dor, função — Oswestry/Roland-Morris, atividade/trabalho, sono/humor, uso de analgésicos); metas FUNCIONAIS (não "dor zero"); desprescrever opioides/BZD/relaxantes crônicos; encaminhar: fisioterapia (exercício supervisionado/educação — todos), psicologia (TCC/ACT) se alto risco/catastrofização/depressão, reumatologia (espondiloartrite/doença inflamatória), neurocirurgia/ortopedia de coluna (déficit progressivo, cauda equina — urgente; radiculopatia/estenose refratárias), clínica de dor multidisciplinar (refratária/opioide), medicina do trabalho (adaptação/retorno); atestado: curto, com retorno ao trabalho modificado; benefício INSS: laudo funcional']}],casa:[{v:'USO ORAL (adjuvante — o tratamento principal é exercício + educação)',i:[['Duloxetina 30 mg (→ 60 mg após 1–2 semanas) — dor crônica persistente, com ou sem humor deprimido/sono ruim','30 cápsulas','Tomar 1 cápsula pela manhã com alimento; manter ≥ 3 meses se benefício (reavaliar); náusea inicial passa; não parar de repente'],['OU Amitriptilina 25 mg (10–25 mg) — dor noturna/sono, < 65 anos sem cardiopatia/glaucoma/prostatismo','30 comprimidos','Tomar ½–1 comprimido 2 h antes de dormir (boca seca/sonolência matinal — reduzir)'],['Naproxeno 500 mg (ou ibuprofeno 600 mg 8/8 h / celecoxibe 200 mg 1×/dia se risco GI) — SOMENTE em crises, por poucos dias','14 comprimidos','Tomar 1 comprimido de 12/12 h após as refeições por até 5–7 dias (máx. 2–4 semanas) nas exacerbações; omeprazol 20 mg em jejum junto se > 65 a/úlcera/AAS; não usar se doença renal/IC/pressão descontrolada'],['Dipirona 500 mg–1 g — resgate','20 comprimidos','Tomar 1 comprimido de 6/6 h se dor intensa (adjuvante; não contínuo)'],['Ciclobenzaprina 5 mg — apenas em exacerbação aguda com espasmo, por ≤ 7 dias','7 comprimidos','Tomar 1 comprimido à noite por até 7 dias (sonolência; não dirigir)'],['Diclofenaco 1% gel','1 bisnaga','Aplicar na região lombar 3×/dia nas crises (efeito modesto; seguro)'],['Desprescrição: reduzir/retirar opioides (tramadol/codeína), benzodiazepínicos, relaxante e AINE de uso contínuo — gradualmente, com plano','—','Conforme orientação; retorno em 4 semanas'],['Encaminhamentos: FISIOTERAPIA (programa de exercícios ativos/educação em dor — 8–12 semanas, depois manter em casa/academia/pilates/caminhada), psicologia (TCC/ACT/mindfulness — se catastrofização/medo do movimento/depressão/ansiedade), clínica de dor ou coluna conforme indicação; reumatologia se suspeita de espondiloartrite','—','—'],['Exames: NÃO repetir RX/RM sem sinais de alarme; se indicado: RM de coluna lombar (déficit/radiculopatia > 6–12 sem/estenose/alarme), HLA-B27 + PCR/VHS + RM de sacroilíacas (dor inflamatória < 45 a), hemograma/VHS/PCR/FA/Ca/eletroforese (alarme/idoso), densitometria (fratura/corticoide/osteoporose), vitamina D','—','—']]}],ori:['A dor lombar crônica RARAMENTE significa lesão grave; na maioria das pessoas os exames mostram "desgaste" normal para a idade (também em quem não tem dor) — a coluna é FORTE, feita para se mover; dor não é igual a dano; repouso, cinta, "cuidado demais" e medo de se mexer PIORAM a dor e a incapacidade; o objetivo é recuperar a FUNÇÃO (trabalho, sono, atividades) — a dor diminui depois','EXERCÍCIO é o tratamento: 30 min/dia (caminhar, bicicleta, natação/hidro) + fortalecimento de tronco/core e alongamento 2–3×/semana (pilates, yoga, musculação orientada, fisioterapia) — comece devagar, aumente aos poucos ("pacing": fazer um pouco todo dia, não "tudo no dia bom e nada no dia ruim"); dor leve durante/após o exercício é esperada e segura; escolha algo que goste e consiga manter por toda a vida','Rotina: levantar da cama e cadeira com frequência (a cada 30–60 min), variar posições, ergonomia no trabalho (apoio lombar, tela na altura dos olhos, pés apoiados), colchão médio/firme, dormir de lado com travesseiro entre os joelhos, carregar peso perto do corpo dobrando os joelhos — mas NÃO ter medo de curvar/levantar peso normal; calor local (bolsa morna 20 min) alivia; perder peso, parar de fumar (piora a dor crônica), dormir bem, cuidar do estresse/ansiedade/depressão (fazem parte da dor crônica — psicoterapia ajuda a dor)','Remédios são coadjuvantes e para CRISES: anti-inflamatório só por poucos dias (risco de estômago, rim, pressão), relaxante só por 1 semana, evitar calmantes e opioides (tramadol/codeína — não funcionam a longo prazo e viciam); duloxetina/amitriptilina demoram 2–4 semanas e são para uso contínuo por meses; não procurar "injeções/bloqueios/desbloqueios" repetidos — alívio curto; cirurgia só em casos específicos (perda de força progressiva, perda de controle da urina/fezes, dor ciática incapacitante que não melhora)','Retorno em 4–6 semanas (ou antes se alarme); trabalho: voltar o mais cedo possível, com adaptações se preciso (ficar afastado por muito tempo dificulta a recuperação); se dor com irradiação para a perna com fraqueza/dormência que piora, ou qualquer sinal de alarme abaixo → avaliação urgente'],al:['Perda de controle da urina ou das fezes, dificuldade para urinar/reter, dormência na região genital/períneo ("em sela"), fraqueza progressiva nas pernas/pé caído → EMERGÊNCIA (cauda equina) — PS imediato','Dor que não melhora deitado/piora à noite, febre, perda de peso sem explicação, história de câncer, uso de corticoide/osteoporose com dor súbita (fratura), infecção recente/uso de drogas injetáveis','Dor abdominal/lombar intensa com massa pulsátil ou pressão baixa (aneurisma — > 60 a); dor lombar + rigidez matinal > 30 min + melhora com exercício em < 45 anos (espondiloartrite — reumatologia)','Humor muito deprimido, pensamentos de morte, uso crescente de analgésicos/calmantes'],ref:'Lancet Low Back Pain Series 2018 (Hartvigsen; Foster; Buchbinder); NICE NG59 Low back pain and sciatica 2016 (atualizado 2020); ACP Clinical Practice Guideline 2017 (Qaseem); WHO Guideline for non-surgical management of chronic primary LBP in adults 2023; ESPAÇO — Hill Lancet 2011 (STarT Back); Cochrane 2021 (exercício — Hayden), 2016 (AINE — Enthoven), 2021 (opioides), 2016 (antidepressivos), 2017 (mindfulness/TCC — Cherkin JAMA 2016); PACE Lancet 2014 (paracetamol); PRECISE NEJM 2017 (pregabalina na ciática); SPACE JAMA 2018 (Krebs — opioides × não opioides); Skelly AHRQ 2020 (não invasivos); MINT JAMA 2017 (radiofrequência); SPORT JAMA 2006 (discectomia); Brinjikji AJNR 2015 (imagem em assintomáticos); SBR/SBOT — Diretrizes de Lombalgia 2018/2022.'},
{n:'Hiperplasia prostática benigna (sintomas urinários do trato inferior)',cid:'N40',sp:'Urologia',ps:[{v:'CONDUTA NO CONSULTÓRIO',i:['Avaliar: IPSS (0–7 leve, 8–19 moderado, 20–35 grave) + questão de qualidade de vida; sintomas de armazenamento (frequência, urgência, noctúria) × esvaziamento (jato fraco, hesitação, esforço, gotejamento, esvaziamento incompleto); diário miccional de 3 dias se noctúria/urgência predominante (poliúria noturna > 33% — IC, apneia, diurético à noite, DM, excesso de líquidos à noite); exame: abdome (globo), toque retal (volume, consistência, nódulos — suspeita → PSA/urologia), genitália/meato, exame neurológico básico; excluir: ITU/prostatite (urina I/urocultura), hematúria (cistoscopia/imagem), DM (glicemia), bexiga hiperativa, estenose de uretra, cálculo vesical, câncer (PSA conforme decisão compartilhada 50–69 a / 45 a se negro ou história familiar; PSA > 4 ou velocidade ↑ → urologia; PSA ↑ também por HPB/prostatite/toque/retenção), medicamentos (anticolinérgicos, descongestionantes, diuréticos, opioides, antidepressivos tricíclicos); creatinina; USG de vias urinárias com resíduo pós-miccional (> 100–200 mL = risco; > 300 → urologia) e volume prostático (> 30–40 g → inibidor de 5α-redutase); urofluxometria se disponível','LEVE (IPSS < 8) ou incômodo mínimo: observação + medidas comportamentais (reduzir líquidos 2–3 h antes de deitar, cafeína/álcool, micção programada/dupla, treinamento vesical, tratar constipação, revisar diuréticos para a manhã, perder peso, atividade física); reavaliar anual','MODERADO–GRAVE (IPSS ≥ 8 com incômodo): ALFABLOQUEADOR 1ª linha (início de ação em dias; não altera progressão): TANSULOSINA 0,4 mg/dia (uroseletivo — menos hipotensão; ejaculação retrógrada; síndrome da íris flácida — avisar oftalmo antes de catarata), DOXAZOSINA 2 → 4–8 mg à noite (SUS; hipotensão postural/tontura — titular; útil se HAS), alfuzosina 10 mg, silodosina 8 mg; PRÓSTATA ≥ 30–40 g (ou PSA ≥ 1,5 ng/mL como proxy): associar INIBIDOR DA 5α-REDUTASE (FINASTERIDA 5 mg ou dutasterida 0,5 mg — reduz volume 20–30% em 6–12 meses, ↓ retenção/cirurgia em 50% — MTOPS/CombAT; efeito só após 3–6 meses; ↓ libido/disfunção erétil/ginecomastia; reduz o PSA à metade — dobrar o valor para interpretar); SINTOMAS DE ARMAZENAMENTO persistentes (urgência/frequência) com resíduo < 150 mL: + ANTIMUSCARÍNICO (solifenacina 5–10 mg; oxibutinina — evitar em idoso) ou MIRABEGRONA 50 mg (β3 — sem efeitos cognitivos; PA); DISFUNÇÃO ERÉTIL associada: TADALAFILA 5 mg/dia (melhora IPSS e ereção; não com nitrato); FITOTERÁPICOS (Serenoa repens/saw palmetto, Pygeum): sem eficácia comprovada (Cochrane) — não recomendar; NOCTÚRIA por poliúria noturna: desmopressina 0,1–0,2 mg à noite (< 65 a; Na sérico — hiponatremia) — urologia','RETENÇÃO URINÁRIA AGUDA: sondagem vesical (Foley 16–18 F; se falha — urologia), iniciar alfabloqueador e tentar retirar a sonda em 3–7 dias (TWOC — sucesso 50–60%); se falha → sonda + cirurgia; retenção crônica com resíduo > 300 mL/hidronefrose/IRA/infecção de repetição/cálculo/hematúria recorrente/falha clínica → CIRURGIA (RTU de próstata — padrão até 80 g; enucleação a laser — HoLEP/ThuLEP; vaporização; prostatectomia simples > 80–100 g; técnicas minimamente invasivas — UroLift/Rezum — em selecionados)','SEGUIMENTO: 4–6 semanas após iniciar alfabloqueador (sintomas, PA ortostática, IPSS), 3–6 meses após 5-ARI; depois anual: IPSS, urina I, creatinina (se resíduo/retenção), PSA (se em rastreio — lembrar de dobrar sob finasterida), resíduo pós-miccional se piora; ENCAMINHAR À UROLOGIA: toque suspeito/PSA alterado, hematúria, retenção, resíduo > 200–300 mL, hidronefrose/IRA, ITU de repetição, cálculo vesical, falha/intolerância ao tratamento clínico (3–6 meses), < 45–50 anos, sintomas neurológicos, incontinência, desejo de cirurgia']}],casa:[{v:'USO ORAL',i:[['Tansulosina 0,4 mg (ou Doxazosina 2 mg — SUS: 1 cp à noite por 7 dias, depois 4 mg; máx. 8 mg)','30 comprimidos','Tomar 1 comprimido 1×/dia, 30 min após a mesma refeição (tansulosina) ou ao deitar (doxazosina); levantar devagar nos primeiros dias (tontura); avisar o oftalmologista se for operar catarata'],['+ Finasterida 5 mg (ou Dutasterida 0,5 mg) — se próstata ≥ 30–40 g ou PSA ≥ 1,5','30 comprimidos','Tomar 1 comprimido 1×/dia, uso contínuo (efeito pleno em 6 meses; mantém a redução enquanto usar); o PSA cai pela metade (informar quem dosar); mulheres grávidas não devem manipular o comprimido partido'],['+ Solifenacina 5 mg (→ 10 mg) ou Mirabegrona 50 mg (preferir em idoso/cognição) — se urgência/frequência persistirem com resíduo < 150 mL','30 comprimidos','Tomar 1 comprimido 1×/dia (boca seca/constipação com solifenacina; medir PA com mirabegrona)'],['OU Tadalafila 5 mg — se disfunção erétil associada (sem nitrato/hipotensão)','30 comprimidos','Tomar 1 comprimido 1×/dia no mesmo horário'],['Exames: urina I + urocultura, creatinina, glicemia, PSA (após decisão compartilhada; antes do toque/sem ITU/relação 48 h), USG de vias urinárias com resíduo pós-miccional e volume prostático; diário miccional 3 dias (se noctúria); IPSS a cada consulta','—','Levar ao retorno em 4–6 semanas (alfabloqueador) e 6 meses (finasterida)'],['Sondagem vesical de demora (Foley 16–18 F) — se retenção aguda; retirar em 3–7 dias após iniciar alfabloqueador (teste de micção)','—','Urologia se falha']]}],ori:['A próstata aumentada é comum com a idade e NÃO é câncer (são doenças diferentes; o PSA/toque servem para avaliar o risco de câncer separadamente); o tratamento alivia os sintomas e, com a finasterida, reduz o crescimento e a chance de "travar a urina" ou precisar operar','Medidas que ajudam: reduzir líquidos nas 2–3 h antes de dormir (concentrar a ingestão de dia), evitar café/chá preto/mate/refrigerante/álcool (irritam a bexiga e aumentam a urina), urinar antes de deitar e "duas vezes" (esperar 30 s e tentar de novo), não segurar por muito tempo nem urinar "por precaução" toda hora (treinar intervalos de 2–3 h), tratar constipação, perder peso e caminhar; diuréticos: tomar pela manhã (conversar); evitar remédios para gripe/alergia com descongestionante ou anti-histamínico sedativo e antiespasmódicos (podem causar retenção); tratar diabetes','Tansulosina/doxazosina: aliviam em alguns dias (jato, frequência); podem dar tontura ao levantar (principalmente nos primeiros dias — levantar devagar, tomar à noite) e ejaculação "seca" (sem perigo); se for operar CATARATA, avisar o oftalmologista que usa; Finasterida: demora 3–6 meses para fazer efeito e deve ser contínua; pode reduzir o desejo sexual/ereção em uma minoria (reversível); reduz o PSA pela metade — avisar quem pedir o exame; não deve ser manuseada por grávidas','Retorno em 4–6 semanas para ver a resposta e a pressão, depois a cada 6–12 meses com exames (urina, creatinina, PSA se indicado); urologista se sintomas persistirem, sangue na urina, infecções repetidas ou retenção'],al:['Não conseguir urinar com bexiga cheia e dor (RETENÇÃO AGUDA) → PS imediatamente (sonda)','Sangue na urina, febre com dor para urinar/dor lombar (infecção/prostatite), dor nos flancos, inchaço de pernas/pouca urina (rim)','Tontura intensa/desmaio ao levantar (ajustar alfabloqueador), nódulo na mama/dor mamária (finasterida), piora progressiva do jato apesar do tratamento, incontinência por transbordamento (gotejamento contínuo com bexiga sempre cheia)','PSA subindo rápido, toque alterado, emagrecimento, dor óssea (investigar câncer)'],ref:'AUA/SUFU Guideline — Management of LUTS Attributed to BPH 2021 (amended 2023/2024) (Lerner/Sandhu); EAU Guidelines on Non-neurogenic Male LUTS 2024 (Gravas/Cornu); SBU — Diretrizes de HPB 2019/2023; NICE CG97 (2010/2015); MTOPS NEJM 2003 (McConnell); CombAT Eur Urol 2010 (Roehrborn); Cochrane 2012 (saw palmetto — Tacklind: sem benefício), 2014 (tansulosina), 2019 (tadalafila); PLESS NEJM 1998 (finasterida — retenção/cirurgia); Barry 1992 (IPSS); MS — Rastreamento de câncer de próstata (INCA 2023: não recomenda rastreio populacional; decisão compartilhada).'},
{n:'Enxaqueca — profilaxia (ambulatório)',cid:'G43.0 / G43.1 / G43.7',sp:'Neurologia',ps:[{v:'CONDUTA NO CONSULTÓRIO',i:['Confirmar enxaqueca (ICHD-3: ≥ 5 crises de 4–72 h, ≥ 2 de: unilateral/pulsátil/moderada-intensa/piora com atividade + náusea/vômito ou foto+fonofobia; aura em 25%) e excluir alarme (SNOOP4 — imagem só se alarme/exame alterado/mudança de padrão); classificar: EPISÓDICA (< 15 dias/mês) × CRÔNICA (≥ 15 dias de cefaleia/mês por > 3 meses, ≥ 8 com características de enxaqueca); DIÁRIO de cefaleia (dias, intensidade, analgésicos, gatilhos, menstruação) + MIDAS/HIT-6 (incapacidade); identificar CEFALEIA POR USO EXCESSIVO DE MEDICAÇÃO (≥ 15 dias/mês de analgésico simples ou ≥ 10 de triptano/opioide/combinação por > 3 meses) — presente em 50–80% da crônica: tratar primeiro (retirada abrupta do analgésico simples/triptano — orientar piora transitória 2–10 dias; desmame se opioide/BZD/barbitúrico; iniciar profilático junto — topiramato/anti-CGRP/toxina funcionam mesmo durante); comorbidades que guiam a escolha: HAS, obesidade, depressão/ansiedade, insônia, epilepsia, asma, Raynaud, gestação/desejo de engravidar, SOP, TAB','INDICAÇÕES DE PROFILAXIA: ≥ 4 dias de enxaqueca/mês ou ≥ 2 crises incapacitantes/mês, crises prolongadas/refratárias ao agudo, uso de agudo ≥ 2 dias/semana (risco de uso excessivo), aura prolongada/hemiplégica/com tronco, enxaqueca crônica, preferência do paciente; ORAIS DE 1ª LINHA (iniciar baixo, titular a cada 1–2 semanas, testar por ≥ 8–12 semanas na dose-alvo antes de julgar; meta: ↓ ≥ 50% dos dias): PROPRANOLOL 40 → 80–160 mg/dia (ou metoprolol 50–200; atenolol) — HAS/ansiedade/tremor; não em asma/bradicardia/depressão/DM com hipoglicemia; AMITRIPTILINA 10 → 25–75 mg à noite — insônia/depressão/tensional associada; ganho de peso/boca seca/sonolência; nortriptilina (menos sedativa); TOPIRAMATO 25 → 50–100 mg/dia (12/12 h) — obesidade/epilepsia; parestesias, lentificação cognitiva/"palavra na ponta da língua", litíase, glaucoma agudo, teratogênico (contracepção; ↓ eficácia de ACO > 200 mg); ÁCIDO VALPROICO/DIVALPROATO 500–1.000 mg/dia — epilepsia/TAB; NÃO em mulher em idade fértil (teratogênico), hepatopatia; CANDESARTANA 16–32 mg (ou lisinopril 10–20) — HAS/intolerância a BB (boa tolerância; evidência moderada); FLUNARIZINA 5–10 mg à noite (3–6 meses; ganho de peso, depressão, parkinsonismo em idosos — evitar > 60 a); VENLAFAXINA 75–150 mg (depressão/ansiedade); 2ª linha/complementares: riboflavina 400 mg/dia, magnésio 400–600 mg (citrato — aura/menstrual), coenzima Q10 100 mg 3×/d, melatonina 3 mg (evidência modesta, baixo risco); gabapentina: fraca; lamotrigina: só aura frequente (não dor)','TERAPIAS ESPECÍFICAS (falha/intolerância/contraindicação a ≥ 2–3 orais, ou crônica com incapacidade — neurologia; alto custo/judicialização): ANTICORPOS ANTI-CGRP (erenumabe 70–140 mg SC/mês; fremanezumabe 225 mg/mês ou 675 mg/3 m; galcanezumabe 240 → 120 mg/mês; eptinezumabe EV) — eficazes em episódica e crônica, inclusive com uso excessivo; resposta em 4–12 semanas; constipação/HAS (erenumabe); evitar gestação/DCV grave; GEPANTES orais (atogepant 60 mg/dia; rimegepant 75 mg em dias alternados — também agudo); TOXINA BOTULÍNICA A 155–195 U (PREEMPT — só enxaqueca CRÔNICA; a cada 12 semanas; SUS em alguns estados); neuromodulação (nVNS, estimulação supraorbital/trigeminal remota) como adjuvante','TRATAMENTO AGUDO OTIMIZADO (reduz necessidade de profilaxia): AINE (naproxeno 550, ibuprofeno 600, cetoprofeno) + antiemético (metoclopramida/domperidona) cedo; triptano (sumatriptano 50–100 / naratriptano 2,5 / rizatriptano 10 / zolmitriptano 2,5) ± AINE nas moderadas-graves — limitar a ≤ 9 dias/mês (triptano) e ≤ 14 (simples); lasmiditan/gepante (rimegepant/ubrogepant) se contraindicação a triptano (DCV); NUNCA opioides/ergotamina combinada (Cefaliv®/Migraliv® — cronificação/uso excessivo) ou dipirona+cafeína+ergotamina de rotina; ENXAQUECA MENSTRUAL: profilaxia perimenstrual (naproxeno 550 12/12 h ou frovatriptano 2,5 12/12 h do −2 ao +3 dia; ACO contínuo sem pausa — só se SEM aura); ENXAQUECA COM AURA: contraindicação a estrogênio (↑ AVC) — progestágeno isolado/DIU/não hormonal; GESTAÇÃO: não farmacológico, magnésio, propranolol/amitriptilina baixa dose se necessário (evitar topiramato/valproato/candesartana/anti-CGRP); paracetamol/metoclopramida no agudo (triptano pontual aceitável)','NÃO FARMACOLÓGICO (nível A — associar sempre): regularidade (sono, refeições, hidratação, cafeína constante/baixa), exercício aeróbico 30–40 min 3×/sem (↓ frequência como profilático), TCC/relaxamento/biofeedback/mindfulness, manejo de gatilhos sem evitação excessiva, controle de peso/apneia, cessar tabagismo, tratar depressão/ansiedade/insônia; acupuntura: evidência moderada (Cochrane); SEGUIMENTO: 4–8 semanas após iniciar (tolerância), 3 meses (eficácia — diário: dias/mês, MIDAS); manter 6–12 meses após controle → retirada gradual; trocar/associar se < 50% de resposta após 8–12 semanas na dose adequada; ENCAMINHAR à neurologia: crônica, uso excessivo refratário, falha de 2–3 profiláticos, aura atípica/prolongada/hemiplégica, dúvida diagnóstica, indicação de anti-CGRP/toxina, gestante refratária, criança/adolescente (profilaxia: flunarizina/propranolol/amitriptilina/topiramato ≥ 12 a; CHAMP: placebo = fármaco — priorizar estilo de vida/TCC)']}],casa:[{v:'USO ORAL — PROFILAXIA (escolher 1 pelo perfil; titular; manter ≥ 3 meses na dose-alvo)',i:[['Propranolol 40 mg (ou 10/80 mg; ou atenolol 25–100 mg / metoprolol 50–200 mg) — se HAS, ansiedade, tremor, palpitações; sem asma/bradicardia','60–120 comprimidos','Tomar ½ comprimido (20 mg) de 12/12 h por 1 semana, depois 1 cp de 12/12 h (80 mg/dia); aumentar a cada 2 semanas até 120–160 mg/dia se necessário (FC > 55); não suspender bruscamente'],['OU Amitriptilina 25 mg (10 mg em idosos/sensíveis) — se insônia, depressão, cefaleia tensional associada, dor crônica','30 comprimidos','Tomar ½ comprimido (12,5 mg) 2 h antes de deitar por 1–2 semanas, depois 1 comprimido (25 mg); aumentar até 50–75 mg à noite se necessário (boca seca/sonolência matinal/ganho de peso)'],['OU Topiramato 25 mg (comprimidos de 25/50/100) — se sobrepeso/obesidade, epilepsia; usar contracepção eficaz','60 comprimidos','Tomar 1 cp (25 mg) à noite por 1 semana → 25 mg 12/12 h → 50 mg à noite + 25 manhã → 50 mg 12/12 h (100 mg/dia), aumentando a cada 7 dias; beber 2 L de água/dia (pedras); formigamento é comum; parar se lentificação cognitiva importante/alteração visual'],['OU Candesartana 16 mg (8 → 16–32 mg) — se HAS ou intolerância aos demais','30 comprimidos','Tomar 1 comprimido 1×/dia (PA/creatinina/K em 4 semanas; não em gestação)'],['OU Flunarizina 10 mg (5 mg em > 60 a/magros) — alternativa (3–6 meses)','30 comprimidos','Tomar 1 comprimido à noite (sonolência/ganho de peso/depressão — avisar); não em idosos/parkinsonismo/depressão'],['OU Divalproato de sódio 250–500 mg (apenas homens ou mulheres sem possibilidade de gestar; epilepsia/TAB)','60 comprimidos','Tomar 250 mg 12/12 h → 500 mg 12/12 h; hemograma/TGO/TGP em 1–3 meses'],['Complementares (opcionais, baixo risco): Riboflavina 400 mg 1×/dia · Magnésio (citrato/quelato) 400–600 mg à noite · Coenzima Q10 100 mg 3×/dia · Melatonina 3 mg ao deitar','30–90 unidades','Uso diário por ≥ 3 meses; efeito modesto'],['Anti-CGRP (ex.: erenumabe 70–140 mg SC 1×/mês; galcanezumabe 240 mg → 120 mg/mês; fremanezumabe 225 mg/mês) ou Toxina botulínica A 155–195 U a cada 12 semanas (enxaqueca CRÔNICA) — neurologia, após falha de 2–3 orais','conforme prescrição especializada','Aplicação mensal SC (anti-CGRP); avaliar resposta em 3 meses']]},{v:'USO ORAL — CRISE (limite: triptano ≤ 9 dias/mês; analgésico simples/AINE ≤ 14 dias/mês)',i:[['Naproxeno 550 mg (ou ibuprofeno 600 mg / cetoprofeno 100 mg) + Metoclopramida 10 mg (ou domperidona 10 mg)','10 + 10 comprimidos','Ao INÍCIO da dor: metoclopramida 1 cp e, 15–20 min depois, naproxeno 1 cp; repetir o AINE em 8–12 h se necessário (máx. 2/dia)'],['Sumatriptano 50 mg (ou rizatriptano 10 mg orodispersível / naratriptano 2,5 mg / zolmitriptano 2,5 mg) — crises moderadas–graves; sem doença coronariana/AVC/HAS não controlada/gestação','4–6 comprimidos','Tomar 1 comprimido ao início da dor (não na aura), junto com o AINE; repetir 1× após 2 h se necessário (máx. 2/dia; ≤ 9 dias/mês)'],['Dipirona 1 g — crises leves/resgate','10 comprimidos','Tomar 1 comprimido ao início da dor; repetir em 6 h se necessário (≤ 14 dias/mês)'],['NÃO usar: ergotamina/combinações (Cefaliv®, Migraliv®, Ormigrein®), opioides (tramadol, codeína), dipirona+cafeína+ergotamina de rotina, analgésicos > 2 dias/semana','—','—'],['Diário de cefaleia (app: Migraine Buddy / caderno): dias com dor, intensidade, duração, remédios usados, menstruação, gatilhos — levar a cada consulta; MIDAS/HIT-6','—','Retorno em 4–8 semanas e em 3 meses']]}],ori:['A PROFILAXIA é um remédio tomado TODOS OS DIAS para reduzir o número e a intensidade das crises (meta: pelo menos metade); demora 4 a 12 semanas para fazer efeito pleno — não desista nas primeiras semanas; a dose começa baixa e sobe aos poucos; dura em geral 6–12 meses e depois é retirada gradualmente; se um não funcionar ou incomodar, há vários outros','CRISE: tratar CEDO (nos primeiros 30–60 min, com dose completa) — antiemético primeiro, depois o anti-inflamatório ± triptano; deitar em local escuro/silencioso, compressa fria, hidratar; e CONTAR os dias: analgésico comum/anti-inflamatório no máximo 14 dias por mês e triptano no máximo 9 — usar mais que isso causa "dor de cabeça por excesso de remédio" (dor quase diária que só melhora quando se para o analgésico — se já estiver assim, a retirada é parte do tratamento e os primeiros 7–10 dias podem ser piores); nunca usar remédios com ergotamina (Cefaliv/Migraliv) ou opioides','ROTINA é o melhor remédio: dormir e acordar em horário regular (7–8 h), não pular refeições (comer a cada 3–4 h), beber 2 L de água, cafeína pouca e constante (não variar — ex.: 1 café de manhã todo dia), exercício aeróbico 30–40 min 3–5×/semana (reduz crises tanto quanto remédio), gerenciar estresse (TCC, relaxamento, respiração, mindfulness, biofeedback), limitar álcool (vinho tinto) e identificar seus gatilhos no diário (sem viver evitando tudo); tratar insônia, ansiedade, depressão, ronco/apneia e manter o peso','Mulheres: enxaqueca COM AURA → anticoncepcional com estrogênio é contraindicado (risco de AVC) — usar progestágeno isolado/DIU/outros; crises menstruais: prevenção nos dias da menstruação; se planeja engravidar ou engravidou: avisar (alguns profiláticos — topiramato, valproato, candesartana — não podem ser usados)','Retorno em 4–8 semanas (tolerância/ajuste) e em 3 meses com o diário (eficácia); encaminhamento à neurologia se não responder a 2–3 profiláticos ou se a dor for quase diária — há tratamentos novos (anticorpos anti-CGRP, toxina botulínica)'],al:['Dor de cabeça SÚBITA e explosiva ("a pior da vida"), ou com febre e rigidez de nuca, ou com fraqueza/dormência de um lado, dificuldade de falar, visão dupla/perda visual que não passa em 1 h, confusão, convulsão, após trauma → SAMU 192/PS','Mudança do padrão habitual: dor nova e diferente, progressiva, que acorda à noite, piora ao deitar/tossir, com vômitos em jato, em > 50 anos, em gestante/puérpera, em imunossuprimido','Dor em aperto no peito/falta de ar após triptano (parar e avaliar); batimentos muito lentos/tontura/desmaio (propranolol); formigamentos intensos/dificuldade de achar palavras/dor nos olhos súbita com visão turva (topiramato — glaucoma agudo: suspender e PS); tristeza profunda/pensamentos de morte (flunarizina/propranolol/topiramato — avisar)'],ref:'Sociedade Brasileira de Cefaleia — Recomendações para o tratamento profilático da enxaqueca 2022 (Arq Neuropsiquiatr) e Consenso 2019; AHS Consensus Statement 2021/2024 (Ailani — integração de novos tratamentos); EHF Guideline 2022 (anti-CGRP — Sacco) e 2019 (toxina); AAN/AHS 2012 (Silberstein — profilaxia episódica) e 2019 (pediatria — Oskoui); ICHD-3 2018; NICE CG150 (2012/2021); Cochrane 2016 (acupuntura — Linde), 2021 (propranolol), 2013 (topiramato/valproato), 2023 (anti-CGRP); PREEMPT (Dodick Headache 2010); CHAMP NEJM 2017 (Powers); Stovner Cephalalgia 2014 (candesartana × propranolol); Diener Lancet Neurol 2004 (cefaleia por uso excessivo); Burch Neurol Clin 2019.'},
{n:'Deficiência de vitamina B12 e de vitamina D (adulto)',cid:'E53.8 / E55.9',sp:'Clínica geral',ps:[{v:'CONDUTA NO CONSULTÓRIO',i:['VITAMINA B12 — QUEM TESTAR (não rastrear a população geral): anemia macrocítica (VCM > 100) ou normocítica inexplicada, pancitopenia, neuropatia periférica/parestesias/ataxia/alteração de sensibilidade vibratória/propriocepção, declínio cognitivo/demência/depressão de início recente, glossite, VEGETARIANOS/VEGANOS, > 60–65 anos, uso prolongado de METFORMINA (≥ 4 anos — dosar anual) ou IBP/antagonistas H2, gastrectomia/BARIÁTRICA/ressecção ileal/DII/celíaca/pancreatite crônica, anemia perniciosa (gastrite atrófica autoimune — anti-fator intrínseco/anti-célula parietal; ↑ risco de Ca gástrico — EDA), HIV, alcoolismo, óxido nitroso; EXAMES: B12 sérica (< 200 pg/mL = deficiente; 200–300 = limítrofe → confirmar com homocisteína ↑ e/ou ácido metilmalônico ↑ — mais sensíveis), hemograma + VCM + reticulócitos, esfregaço (neutrófilos hipersegmentados), folato, ferritina (deficiência combinada mascara macrocitose), TSH, LDH/bilirrubina indireta (eritropoese ineficaz), anti-fator intrínseco; não dosar B12 após injeção/suplemento recente; biotina em altas doses interfere nos ensaios','TRATAMENTO B12: sintomas NEUROLÓGICOS, anemia grave, má absorção (perniciosa/bariátrica/ressecção ileal) → CIANOCOBALAMINA (ou hidroxocobalamina) IM 1.000 mcg/dia por 7 dias (ou em dias alternados) → 1.000 mcg/semana por 4 semanas → 1.000 mcg/mês INDEFINIDAMENTE se causa irreversível (perniciosa, cirurgia), ou até corrigir a causa; sem sintomas neurológicos/dieta/metformina/IBP/idoso com absorção preservada → ORAL em ALTA DOSE 1.000–2.000 mcg/dia (absorção passiva de 1% — tão eficaz quanto IM, inclusive em perniciosa, com adesão — Cochrane 2018), sublingual/spray equivalentes; RESPOSTA: reticulócitos ↑ em 5–7 dias, Hb normaliza em 6–8 semanas (repor ferro/folato se necessário — demanda ↑), neuropatia melhora em semanas–meses (déficit > 6–12 meses pode ser irreversível); hipocalemia nos primeiros dias em anemia grave (monitorar K); NÃO dar ácido fólico isolado sem excluir deficiência de B12 (corrige a anemia e mascara/agrava a neuropatia); vegetarianos/veganos: suplementar sempre (B12 só existe em alimentos de origem animal/fortificados); gestante vegana: B12 + folato; metformina: manter e repor B12','VITAMINA D — QUEM DOSAR (25-OH-D; não rastrear a população geral saudável — SBEM/SBPC 2023/Endocrine Society 2024): osteoporose/osteopenia/fratura por fragilidade, idosos institucionalizados/com quedas, raquitismo/osteomalácia (dor óssea, fraqueza proximal, FA ↑, Ca/P ↓, PTH ↑), DRC/hepatopatia, má absorção (celíaca, DII, bariátrica, fibrose cística), hiperparatireoidismo, uso de anticonvulsivantes/corticoide/antirretrovirais/cetoconazol, obesidade grave (sequestro), gestantes de risco, pele escura com baixa exposição, sarcoidose/granulomatosas (hipercalcemia); VALORES (SBEM/SBPC): > 20 ng/mL desejável para população saudável até 60 a; 30–60 ng/mL para grupos de risco (osteoporose, idosos, má absorção, DRC, gestantes, obesos, etc.); < 10–12 = deficiência grave (risco de osteomalácia); > 100 = toxicidade; NÃO há benefício comprovado de suplementar pessoas com níveis normais para prevenir câncer, DCV, diabetes, infecções, depressão, quedas (VITAL, D-Health, DO-HEALTH, Cochrane — megadoses até ↑ quedas/fraturas); benefício: osteomalácia/raquitismo, osteoporose (junto com cálcio e antirreabsortivo), deficiência comprovada, idosos institucionalizados (↓ quedas com dose diária 800–1.000 UI + cálcio)','TRATAMENTO VIT D: DEFICIÊNCIA (< 20): colecalciferol (D3) 7.000 UI/dia ou 50.000 UI/semana por 6–8 semanas (dose de ataque total ~300.000–400.000 UI) → MANUTENÇÃO 1.000–2.000 UI/dia (ou 7.000–14.000 UI/semana; 50.000 UI/mês em obesos/má absorção — até 3× a dose); INSUFICIÊNCIA em grupo de risco (20–30): 1.000–2.000 UI/dia; evitar megadoses anuais (500.000 UI — ↑ quedas/fraturas) e "bolus" mensais > 100.000; calcifediol (25-OH-D) 20 mcg/dia em hepatopatia/má absorção; calcitriol só em DRC avançada/hipoparatireoidismo (não para deficiência); garantir CÁLCIO dietético 1.000–1.200 mg/dia (suplementar só a diferença); dosar 25-OH-D após 3 meses de reposição (depois anual ou conforme risco); Ca sérico/urinário se doses altas, granulomatose, litíase; SOL: 15–20 min, 3×/sem, braços/pernas sem protetor fora do pico (10–15 h) — insuficiente em pele escura/idosos/latitudes altas; alimentos: peixes gordos, gema, fígado, leite fortificado (pouco)','SEGUIMENTO B12: hemograma + reticulócitos em 1–2 semanas (anemia) e 8 semanas; B12 (ou AMM) em 3 meses (manutenção oral — garantir adesão); neurológico a cada consulta; perniciosa: EDA basal (atrofia/metaplasia — vigilância de Ca gástrico/carcinoide a cada 3–5 anos), TSH/anti-TPO e glicemia (autoimunidade associada); encaminhar: hematologia (pancitopenia/dúvida/refratário), neurologia (mielopatia/neuropatia atípica), gastro (perniciosa/má absorção), endocrino (vit D refratária, hipercalcemia, hiperpara, osteomalácia)']}],casa:[{v:'USO ORAL / IM — VITAMINA B12',i:[['Cianocobalamina 1.000 mcg (ou 5.000 mcg) comprimido/sublingual — deficiência SEM sintomas neurológicos / dieta / metformina / IBP / manutenção','60–90 comprimidos','Tomar 1 comprimido (1.000–2.000 mcg) 1×/dia, em jejum ou longe das refeições, TODOS OS DIAS (ou 2.000 mcg/dia); uso contínuo se a causa persistir (vegetariano, metformina, gastrectomia); B12 em 3 meses'],['OU Cianocobalamina 5.000 mcg/mL (ou hidroxocobalamina 5 mg/mL) injetável IM — sintomas NEUROLÓGICOS, anemia grave, anemia perniciosa, pós-bariátrica/ressecção ileal','7 + 4 + 12 ampolas (1º ano)','Aplicar 1 ampola (1.000 mcg — ou 5.000 mcg conforme apresentação) IM profundo 1×/dia por 7 dias (ou em dias alternados), depois 1×/semana por 4 semanas, depois 1×/mês INDEFINIDAMENTE (perniciosa/cirurgia) ou até corrigir a causa (pode trocar para oral 1.000–2.000 mcg/dia na manutenção se absorver)'],['+ Ácido fólico 5 mg (ou 1–2 mg) — SOMENTE se folato baixo ou demanda ↑ (gestação, hemólise), e SEMPRE junto/após a B12 (nunca isolado)','30 comprimidos','Tomar 1 comprimido 1×/dia por 1–4 meses'],['+ Sulfato ferroso 40–60 mg Fe (dias alternados) — se ferritina < 30–50 (a recuperação da anemia consome ferro)','30 comprimidos','Jejum com vitamina C, por 3 meses'],['Exames: B12 sérica (± homocisteína/ácido metilmalônico se 200–300), hemograma + VCM + reticulócitos, folato, ferritina, TSH, LDH, anti-fator intrínseco (perniciosa), K na 1ª semana se anemia grave; controle: reticulócitos em 1–2 semanas, hemograma em 8 semanas, B12 em 3 meses; EDA se perniciosa','—','Levar ao retorno']]},{v:'USO ORAL — VITAMINA D',i:[['Colecalciferol (vitamina D3) 7.000 UI cápsula/comprimido (ou 50.000 UI semanal; ou gotas 200 UI/gota = 35 gotas) — DEFICIÊNCIA (25-OH-D < 20 ng/mL)','8–12 cápsulas (7.000 UI) ou 56 cápsulas (1.000 UI)','ATAQUE: 7.000 UI 1×/dia (ou 50.000 UI 1×/semana) por 6–8 semanas, com uma refeição que contenha gordura; depois MANUTENÇÃO: 1.000–2.000 UI/dia (ou 7.000 UI 1×/semana); dosar 25-OH-D após 3 meses (alvo 30–60 ng/mL em grupos de risco)'],['Colecalciferol 1.000–2.000 UI/dia (ou 7.000–14.000 UI 1×/semana) — INSUFICIÊNCIA (20–30) em grupo de risco ou manutenção; obesos/má absorção: 2–3× (até 50.000 UI/semana)','30–60 cápsulas','Tomar 1×/dia (ou semanal) com refeição; uso contínuo'],['Cálcio pela dieta (1.000–1.200 mg/dia = 3 porções de laticínios) — suplementar (carbonato/citrato 500 mg com refeição) só a diferença','—','Não exceder 500 mg por dose de suplemento'],['NÃO indicado: megadose anual (500.000 UI), "vitamina D injetável" mensal de rotina, doses > 4.000 UI/dia sem dosagem/controle, suplementar quem tem nível normal "para imunidade/prevenir doenças" (sem benefício; risco de hipercalcemia/pedras)','—','—'],['Exames: 25-OH-vitamina D (nos grupos de risco), Ca, P, fosfatase alcalina, PTH, creatinina, albumina (± Ca urinário 24 h se doses altas/litíase); controle em 3 meses, depois anual','—','—']]}],ori:['VITAMINA B12: é essencial para o sangue e os nervos; a deficiência costuma vir de pouca absorção (idade, gastrite, remédios para o estômago — omeprazol —, metformina, cirurgias do estômago/intestino) ou de dieta sem alimentos de origem animal (vegetarianos/veganos precisam suplementar sempre); o comprimido em DOSE ALTA (1.000–2.000 mcg/dia) funciona tão bem quanto a injeção na maioria das pessoas — desde que tomado todos os dias; a injeção é usada quando há sintomas nos nervos (formigamento, desequilíbrio, perda de memória), anemia importante ou doenças que impedem a absorção; nesses casos a manutenção mensal pode ser para a vida toda; a anemia melhora em 2 meses, os sintomas neurológicos em semanas a meses (quanto mais cedo tratar, mais se recupera); fontes: carnes, peixes, ovos, leite/queijo, alimentos fortificados; não tomar ácido fólico sozinho sem orientação','VITAMINA D: a maioria das pessoas saudáveis NÃO precisa dosar nem suplementar — o benefício comprovado é para quem tem deficiência, osteoporose, idosos, doenças de absorção/rim/fígado, obesidade importante, uso de certos remédios; suplementos em excesso ("megadoses", injeções mensais de rotina, > 4.000 UI/dia sem controle) NÃO previnem câncer, infarto, gripe ou Covid e podem causar excesso de cálcio, pedras nos rins e até mais quedas; se prescrita: tomar com uma refeição com gordura, na dose e frequência indicadas, e repetir o exame em 3 meses; SOL: 15–20 min, 3×/semana, braços e pernas, fora do horário de pico (evitar 10–15 h), sem queimar — pele escura/idosos produzem menos; cálcio: 3 porções de laticínios (ou alternativas) por dia; exercício com peso para os ossos','Levar sempre a lista de remédios (omeprazol/metformina reduzem B12; anticonvulsivantes/corticoide reduzem vitamina D); retorno com os exames de controle (B12: hemograma em 1–2 semanas e 2 meses; vitamina D: 3 meses); se tiver anemia perniciosa: acompanhamento com endoscopia periódica (gastro) e exames de tireoide/glicemia (doenças autoimunes associadas)'],al:['B12: formigamento/dormência que piora, desequilíbrio ao andar/no escuro, fraqueza nas pernas, perda de memória/confusão, alterações de humor/visão — procurar avaliação (pode ser dano neurológico em progressão); palidez intensa, falta de ar, palpitações (anemia grave); fraqueza/cãibras/palpitações nos primeiros dias de tratamento de anemia grave (potássio)','Vitamina D (excesso): náuseas/vômitos, sede e urina excessivas, constipação, fraqueza, confusão, dor lombar/sangue na urina (pedras) — suspender e dosar cálcio; dor óssea difusa/fraqueza para subir escadas/levantar da cadeira (osteomalácia por deficiência grave)','Emagrecimento, dor abdominal, saciedade precoce, fezes escuras em anemia perniciosa (câncer gástrico — endoscopia)'],ref:'BSH Guidelines — Diagnosis and Treatment of Cobalamin and Folate Disorders 2014 (Devalia) e 2024 update; NICE NG239 Vitamin B12 deficiency 2024; Stabler NEJM 2013 (B12 — revisão); Cochrane 2018 (Wang — B12 oral × IM); Green Nat Rev Dis Primers 2017; ADA 2024 (metformina e B12); SBEM/SBPC-ML — Posicionamento sobre Vitamina D 2017 e Atualização 2023 (Moreira/Ferreira — intervalos de referência e grupos de risco); Endocrine Society Clinical Practice Guideline — Vitamin D for Prevention of Disease 2024 (Demay — contra rastreio e suplementação empírica); Holick 2011; VITAL NEJM 2019/2022 (Manson; LeBoff — sem ↓ fraturas); D-Health Lancet Diabetes Endocrinol 2022; DO-HEALTH JAMA 2020; Sanders JAMA 2010 (megadose anual ↑ quedas); Cochrane 2014/2023 (vitamina D — mortalidade/quedas); Bouillon Endocr Rev 2019; USPSTF 2021 (rastreio de vitamina D — evidência insuficiente).'}
);
